#include "statistics.hpp"
// All statistics and bootstrap in native C++. Presentation only consumes output.
std::string json_value(const J&v){if(v.type=="literal")return v.scalar;if(v.type=="string")return qstr(v.scalar);bool first=true;std::string s=v.type=="array"?"[":"{";if(v.type=="array"){for(auto&x:v.array){if(!first)s+=",";first=false;s+=json_value(x);}}else for(auto&[k,x]:v.object){if(!first)s+=",";first=false;s+=qstr(k)+":"+json_value(x);}return s+(v.type=="array"?"]":"}");}
int main(int argc,char**argv){try{require(argc==6,"usage: analyze_stage MATRIX CAMPAIGN AUDIT_RECEIPT cold|cohort NEW_STATS.json");auto matrix=read_json(argv[1]),audit=read_json(argv[3]);files::path campaign=argv[2];std::string stage=argv[4];require((stage=="cold"||stage=="cohort")&&audit.at("stage").scalar==stage&&audit.at("status").scalar=="PASS_ALL_DECLARED_STAGE_EVIDENCE"&&audit.at("matrix_sha256").scalar==digest(argv[1]),"Full stage verification gate required");size_t blocks=stage=="cold"?8:3;std::array<std::vector<double>,3> wall,cpu,rss,online,preparation;std::array<std::array<std::vector<double>,8>,3> per_target;for(auto&v:wall)v.resize(blocks,NAN);std::map<std::string,J> sealed_costs;for(auto&v:audit.at("process_costs").array)sealed_costs.emplace(v.at("id").scalar,v);std::string rows="[",aa="[";bool first=true,aa_first=true;uint64_t capped_walks=0;std::vector<double> aa_spread;
 for(auto&row:matrix.at("rows").array){if(row.at("stage").scalar!=stage)continue;auto id=row.at("id").scalar;auto dir=campaign/id;auto e=read_json((dir/"execution.json").string());require(sealed_costs.count(id)&&sealed_costs.at(id).at("execution_sha256").scalar==digest(dir/"execution.json"),"Execution receipt not sealed by independent audit");require(digest(dir/"stdout.jsonl")==e.at("stdout_sha256").scalar&&digest(dir/"answers.jsonl")==e.at("semantic_sha256").scalar,"Analysis raw evidence seal mismatch");if(id.rfind("aa_",0)==0){if(!aa_first)aa+=",";aa_first=false;aa+="{\"id\":"+qstr(id)+",\"wall_s\":"+e.at("elapsed_process_wall_s").scalar+",\"cpu_s\":"+e.at("cpu_total_s").scalar+",\"peak_rss_bytes\":"+e.at("peak_rss_bytes").scalar+"}";aa_spread.push_back(real(e.at("elapsed_process_wall_s")));continue;}
 auto role=row.at("role").scalar;size_t r=role=="control"?0:role=="selected"?1:2;size_t offset=id.find('_')+1;size_t block=std::stoull(id.substr(offset,id.find('_',offset)-offset));require(block<blocks&&std::isnan(wall[r][block]),"Missing/duplicate primary block");wall[r][block]=real(e.at("elapsed_process_wall_s"));cpu[r].push_back(real(e.at("cpu_total_s")));rss[r].push_back(real(e.at("peak_rss_bytes")));auto stdout_rows=lines(dir/"stdout.jsonl");std::vector<double> clocks;const J*timing=nullptr;
 for(auto&v:stdout_rows){if(v.at("kind").scalar=="n83_aligned_query_receipt"){require(num(v.at("fixture_index"))==clocks.size(),"Clock order mismatch");clocks.push_back(double(num(v.at("interval_ns")))/1e9);}if(v.object.count("timing_ms"))timing=&v.at("timing_ms");}require(clocks.size()==num(row.at("target_count")),"Aligned clock count mismatch");for(size_t j=0;j<clocks.size();j++){size_t target=size_t(num(row.at("target_indices").at(j)));require(target<8,"Target index mismatch");per_target[r][target].push_back(clocks[j]);online[r].push_back(clocks[j]);}
 if(timing){if(r==2)preparation[r].push_back(real(timing->at("setup_total"))/1000.);else preparation[r].push_back((real(timing->at("setup_total"))+real(timing->at("rank_stage"))+real(timing->at("linear_algebra")))/1000.);}
 if(r==2)for(auto&v:lines(dir/"answers.jsonl"))capped_walks+=uint64_t(num(v.at("outcome").at("capped_walks")));
 if(!first)rows+=",";first=false;rows+="{\"id\":"+qstr(id)+",\"role\":"+qstr(role)+",\"block\":"+std::to_string(block)+",\"rank_seed\":"+row.at("rank_seed").scalar+",\"target_indices\":"+json_value(row.at("target_indices"))+",\"wall_s\":"+e.at("elapsed_process_wall_s").scalar+",\"cpu_s\":"+e.at("cpu_total_s").scalar+",\"peak_rss_bytes\":"+e.at("peak_rss_bytes").scalar+",\"aligned_online_s\":[";for(size_t j=0;j<clocks.size();j++){if(j)rows+=",";std::ostringstream x;x<<std::setprecision(17)<<clocks[j];rows+=x.str();}rows+="],\"producer_phase_ms\":"+(timing?json_value(*timing):"null")+",\"execution_sha256\":"+qstr(digest(dir/"execution.json"))+"}";
 }
 rows+="]";aa+="]";uint64_t seed=stage=="cold"?202610157801ULL:202610157802ULL;auto estimates=paired(wall,seed);std::ostringstream out;out<<std::setprecision(17)<<"{\"kind\":\"n83_basis_native_stage_statistics/v1\",\"stage\":"<<qstr(stage)<<",\"primary_blocks\":"<<blocks<<",\"actual_targets_per_process\":"<<(stage=="cold"?1:8)<<",\"bootstrap_draws\":20000,\"bootstrap_seed\":"<<seed<<",\"quantile_convention\":\"type7 linear interpolation; midpoint median\",\"process_summary\":{";for(size_t r=0;r<3;r++){if(r)out<<",";out<<qstr(r==0?"control":r==1?"selected":"rho")<<":{\"wall_s\":"<<descriptive(wall[r])<<",\"cpu_s\":"<<descriptive(cpu[r])<<",\"peak_rss_bytes\":"<<descriptive(rss[r])<<",\"aligned_online_s\":"<<descriptive(online[r])<<",\"producer_preparation_s\":"<<(preparation[r].empty()?"null":descriptive(preparation[r]))<<"}";}out<<"},\"comparisons\":{";for(size_t i=0;i<3;i++){if(i)out<<",";out<<qstr(i==0?"selected_over_rho":i==1?"control_over_rho":"selected_over_control")<<":{\"mean_cost_ratio\":"<<estimates[i].ratio<<",\"conditional_95_percent_interval\":["<<estimates[i].lo<<","<<estimates[i].hi<<"]}";}out<<"},\"all_process_rows\":"<<rows<<",\"online_target_rows\":[";for(size_t target=0;target<8;target++){if(target)out<<",";out<<"{\"target_index\":"<<target;for(size_t r=0;r<3;r++){auto&v=per_target[r][target];require(v.size()==(stage=="cold"?1:3),"Target repeat coverage mismatch");out<<","<<qstr(r==0?"control":r==1?"selected":"rho")<<":{\"recorded_repeats_s\":[";for(size_t i=0;i<v.size();i++){if(i)out<<",";out<<v[i];}out<<"],\"mean_s\":"<<mean(v)<<"}";}out<<",\"selected_over_rho_mean_ratio\":"<<mean(per_target[1][target])/mean(per_target[2][target])<<"}";}out<<"],\"AA_processes\":"<<aa<<",\"AA_wall_larger_over_smaller\":"<<quantile(aa_spread,1)/quantile(aa_spread,0)<<",\"main_rho_capped_walks_retained\":"<<capped_walks<<",\"stage_failures\":0,\"memory_limit_hit\":null,\"inference_limits\":\"Conditional on observed target/preparation blocks on one guest; cohort has only three preparation clusters; online secondary; no 1685-target crossover computed\",\"matrix_sha256\":"<<qstr(digest(argv[1]))<<",\"audit_receipt_sha256\":"<<qstr(digest(argv[3]))<<",\"analysis_source_sha256\":"<<qstr(digest(__FILE__))<<",\"analysis_executable_sha256\":"<<qstr(digest(argv[0]))<<"}\n";create_new(argv[5],out.str());std::cout<<stage<<" selected/rho="<<estimates[0].ratio<<" ["<<estimates[0].lo<<", "<<estimates[0].hi<<"]\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
